    "lib/sparklend-kill-switch/src/interfaces/IKillSwitchOracle.sol": {
      "content": "// SPDX-License-Identifier: AGPL-3.0
pragma solidity >=0.8.0;

import { IPool }             from "aave-v3-core/contracts/interfaces/IPool.sol";
import { IPoolConfigurator } from "aave-v3-core/contracts/interfaces/IPoolConfigurator.sol";

interface IKillSwitchOracle {

    /******************************************************************************************************************/
    /*** Events                                                                                                     ***/
    /******************************************************************************************************************/

    /** 
     *  @dev  Emitted when the oracle is set or updated.
     *  @param oracle    The address of the oracle being set or updated.
     *  @param threshold The oracle price threshold to trigger the kill switch.
     */
    event SetOracle(address indexed oracle, uint256 threshold);

    /** 
     * @dev   Emitted when an oracle is disabled.
     * @param oracle The address of the oracle being disabled.
     */
    event DisableOracle(address indexed oracle);

    /**
     *  @dev   Emitted when the kill switch is triggered by the oracle below its threshold.
     *  @param oracle    The address of the oracle that met the trigger condition.
     *  @param threshold The threshold value that was compared against the price.
     *  @param price     The price that met or exceeded the threshold value.
     */
    event Trigger(address indexed oracle, uint256 threshold, uint256 price);

    /**
     *  @dev   Emitted when the borrow is disabled for an asset.
     *  @param asset The address of the asset whose borrow has been disabled.
     */
    event BorrowDisabled(address indexed asset);

    /**
     *  @dev Emitted when the contract is reset.
     */
    event Reset();

    /******************************************************************************************************************/
    /*** Storage Variables                                                                                          ***/
    /******************************************************************************************************************/

    /**
     *  @dev    Returns the address of the pool configurator.
     *  @return poolConfigurator The address of the pool configurator.
     */
    function poolConfigurator() external view returns (IPoolConfigurator poolConfigurator);

    /**
     *  @dev    Returns the address of the data provider.
     *  @return pool The address of the data provider.
     */
    function pool() external view returns (IPool pool);

    /**
     *  @dev    Returns true if the kill switch has been triggered.
     *  @return _triggered A boolean indicating whether the kill switch has been triggered.
     */
    function triggered() external view returns (bool _triggered);

    /**
     * @dev    Returns the threshold for the provided oracle.
     * @param  oracle The address of the oracle.
     * @return threshold The threshold for the provided oracle.
     */
    function oracleThresholds(address oracle) external view returns (uint256 threshold);

    /******************************************************************************************************************/
    /*** Owner Functions                                                                                            ***/
    /******************************************************************************************************************/

    /**
     * @dev   Sets or updates the oracle with a new threshold value.
     * @param oracle    The address of the oracle to set or update.
     * @param threshold The new threshold value to associate with the oracle.
     */
    function setOracle(address oracle, uint256 threshold) external;

    /**
     * @dev   Disables a specified oracle, preventing it from being used.
     * @param oracle The address of the oracle to disable.
     */
    function disableOracle(address oracle) external;

    /**
     * @dev Reset the module so that the kill switch can only be triggered if one of
     *      the oracles is below the threshold.
     */
    function reset() external;


    /******************************************************************************************************************/
    /*** Getter Functions                                                                                           ***/
    /******************************************************************************************************************/

    /**
     * @dev    Returns the total number of oracles being monitored.
     * @return _numOracles The total number of oracles.
     */
    function numOracles() external view returns (uint256 _numOracles);

    /**
     * @dev    Returns the address of the oracle at a given index.
     * @param  index  The index of the oracle in the storage array.
     * @return oracle The address of the oracle at the specified index.
     */
    function oracleAt(uint256 index) external view returns (address oracle);

    /**
     * @dev    Checks if a given address is an oracle being monitored.
     * @param  oracle     The address to check.
     * @return _hasOracle True if the address is an oracle being monitored.
     */
    function hasOracle(address oracle) external view returns (bool _hasOracle);

    /**
     * @dev    Returns an array containing the addresses of all oracles being monitored.
     * @return _oracles An array of oracle addresses.
     */
    function oracles() external view returns (address[] memory _oracles);

    /******************************************************************************************************************/
    /*** Public Functions                                                                                           ***/
    /******************************************************************************************************************/

    /**
     * @notice Permissionless function to trigger the kill switch.
     * @dev    If the kill switch has not been triggered, the oracle threshold has been defined,
     *         and the oracle is below the threshold, the kill switch is triggered. This will
     *         disable borrowing on all assets. If the kill switch has been triggered, this
     *         function will allow disabling borrowing on all assets until the kill switch is reset.
     * @param  oracle The address of the oracle which is below the threshold. If the kill switch
     *                has been triggered, this parameter is ignored.
     */
    function trigger(address oracle) external;

}
"
    },
    "src/SparkPayloadEthereum.sol": {
      "content": "// SPDX-License-Identifier: AGPL-3.0

pragma solidity ^0.8.0;

import { IERC20 } from "forge-std/interfaces/IERC20.sol";

import { OptionsBuilder } from "lib/xchain-helpers/lib/devtools/packages/oapp-evm/contracts/oapp/libs/OptionsBuilder.sol";

import { IMetaMorpho, MarketParams, Id, IERC4626 } from "metamorpho/interfaces/IMetaMorpho.sol";
import { IMetaMorphoFactory }                      from "metamorpho/interfaces/IMetaMorphoFactory.sol";

import { MarketParamsLib } from "morpho-blue/src/libraries/MarketParamsLib.sol";

import { Arbitrum }  from "spark-address-registry/Arbitrum.sol";
import { Avalanche } from "spark-address-registry/Avalanche.sol";
import { Base }      from "spark-address-registry/Base.sol";
import { Ethereum }  from "spark-address-registry/Ethereum.sol";
import { Gnosis }    from "spark-address-registry/Gnosis.sol";
import { Optimism }  from "spark-address-registry/Optimism.sol";
import { SparkLend } from "spark-address-registry/SparkLend.sol";
import { Unichain }  from "spark-address-registry/Unichain.sol";

import { IALMProxy }         from "spark-alm-controller/src/interfaces/IALMProxy.sol";
import { MainnetController } from "spark-alm-controller/src/MainnetController.sol";

import { IExecutor } from "spark-gov-relay/src/interfaces/IExecutor.sol";

import { IAToken } from "sparklend-v1-core/interfaces/IAToken.sol";
import { IPool }   from "sparklend-v1-core/interfaces/IPool.sol";

import { AMBForwarder }                            from "xchain-helpers/forwarders/AMBForwarder.sol";
import { ArbitrumForwarder, ICrossDomainArbitrum } from "xchain-helpers/forwarders/ArbitrumForwarder.sol";
import { LZForwarder, ILayerZeroEndpointV2 }       from "xchain-helpers/forwarders/LZForwarder.sol";
import { OptimismForwarder }                       from "xchain-helpers/forwarders/OptimismForwarder.sol";


import { SLLHelpers } from "./libraries/SLLHelpers.sol";

import { ITreasuryControllerLike, IArbitrumTokenBridge, IOptimismTokenBridge } from "./interfaces/Interfaces.sol";

import { AaveV3PayloadBase, IEngine } from "./AaveV3PayloadBase.sol";

/**
 * @dev    Base smart contract for Ethereum.
 * @author Phoenix Labs
 */
abstract contract SparkPayloadEthereum is AaveV3PayloadBase(SparkLend.CONFIG_ENGINE) {

    using OptionsBuilder for bytes;

    // These need to be immutable (delegatecall) and can only be set in constructor
    address public immutable PAYLOAD_ARBITRUM;
    address public immutable PAYLOAD_BASE;
    address public immutable PAYLOAD_GNOSIS;
    address public immutable PAYLOAD_OPTIMISM;
    address public immutable PAYLOAD_UNICHAIN;
    address public immutable PAYLOAD_AVALANCHE;

    function execute() public override {
        super.execute();

        if (PAYLOAD_ARBITRUM != address(0)) {
            ArbitrumForwarder.sendMessageL1toL2({
                l1CrossDomain: ArbitrumForwarder.L1_CROSS_DOMAIN_ARBITRUM_ONE,
                target:        Arbitrum.SPARK_RECEIVER,
                message:       _encodePayloadQueue(PAYLOAD_ARBITRUM),
                gasLimit:      1_000_000,
                maxFeePerGas:  50e9,
                baseFee:       block.basefee
            });
        }
        if (PAYLOAD_BASE != address(0)) {
            OptimismForwarder.sendMessageL1toL2({
                l1CrossDomain: OptimismForwarder.L1_CROSS_DOMAIN_BASE,
                target:        Base.SPARK_RECEIVER,
                message:       _encodePayloadQueue(PAYLOAD_BASE),
                gasLimit:      1_000_000
            });
        }
        if (PAYLOAD_GNOSIS != address(0)) {
            AMBForwarder.sendMessageEthereumToGnosisChain({
                target:   Gnosis.AMB_EXECUTOR,
                message:  _encodePayloadQueue(PAYLOAD_GNOSIS),
                gasLimit: 1_000_000
            });
        }
        if (PAYLOAD_OPTIMISM != address(0)) {
            OptimismForwarder.sendMessageL1toL2({
                l1CrossDomain: OptimismForwarder.L1_CROSS_DOMAIN_OPTIMISM,
                target:        Optimism.SPARK_RECEIVER,
                message:       _encodePayloadQueue(PAYLOAD_OPTIMISM),
                gasLimit:      1_000_000
            });
        }
        if (PAYLOAD_UNICHAIN != address(0)) {
            OptimismForwarder.sendMessageL1toL2({
                l1CrossDomain: OptimismForwarder.L1_CROSS_DOMAIN_UNICHAIN,
                target:        Unichain.SPARK_RECEIVER,
                message:       _encodePayloadQueue(PAYLOAD_UNICHAIN),
                gasLimit:      1_000_000
            });
        }
        if (PAYLOAD_AVALANCHE != address(0)) {
            bytes memory options = OptionsBuilder.newOptions().addExecutorLzReceiveOption(500_000, 0);

            LZForwarder.sendMessage({
                _dstEid:        LZForwarder.ENDPOINT_ID_AVALANCHE,
                _receiver:      SLLHelpers.addrToBytes32(Avalanche.SPARK_RECEIVER),
                endpoint:       ILayerZeroEndpointV2(LZForwarder.ENDPOINT_ETHEREUM),
                _message:       _encodePayloadQueue(PAYLOAD_AVALANCHE),
                _options:       options,
                _refundAddress: Ethereum.SPARK_PROXY,
                _payInLzToken:  false
            });
        }
    }

    /**
     * @notice Checks if the star payload is executable in the current block
     * @dev Required, useful for implementing "earliest launch date" or "office hours" strategy
     * @return result The result of the check (true = executable, false = not)
     */
    function isExecutable() external view returns (bool result) {
        result = true;  // TODO Change this
    }

    function getPoolContext() public pure override returns (IEngine.PoolContext memory) {
        return IEngine.PoolContext({networkName: "Ethereum", networkAbbreviation: "Eth"});
    }

    function _encodePayloadQueue(address _payload) internal pure returns (bytes memory) {
        address[] memory targets        = new address[](1);
        uint256[] memory values         = new uint256[](1);
        string[] memory signatures      = new string[](1);
        bytes[] memory calldatas        = new bytes[](1);
        bool[] memory withDelegatecalls = new bool[](1);

        targets[0]           = _payload;
        values[0]            = 0;
        signatures[0]        = "execute()";
        calldatas[0]         = "";
        withDelegatecalls[0] = true;

        return abi.encodeCall(IExecutor.queue, (
            targets,
            values,
            signatures,
            calldatas,
            withDelegatecalls
        ));
    }

    function _upgradeController(address oldController, address newController) internal {
        SLLHelpers.upgradeMainnetController(
            oldController,
            newController
        );
    }

    function _configureAaveToken(address token, uint256 depositMax, uint256 depositSlope) internal {
        SLLHelpers.configureAaveToken(
            Ethereum.ALM_RATE_LIMITS,
            token,
            depositMax,
            depositSlope
        );
    }

    function _configureERC4626Vault(address vault, uint256 depositMax, uint256 depositSlope) internal {
        SLLHelpers.configureERC4626Vault(
            Ethereum.ALM_RATE_LIMITS,
            vault,
            depositMax,
            depositSlope
        );
    }

    function _configureCurvePool(
        address controller,
        address pool,
        uint256 maxSlippage,
        uint256 swapMax,
        uint256 swapSlope,
        uint256 depositMax,
        uint256 depositSlope,
        uint256 withdrawMax,
        uint256 withdrawSlope
    ) internal {
        SLLHelpers.configureCurvePool(
            controller,
            Ethereum.ALM_RATE_LIMITS,
            pool,
            maxSlippage,
            swapMax,
            swapSlope,
            depositMax,
            depositSlope,
            withdrawMax,
            withdrawSlope
        );
    }

    function _transferAssetFromAlmProxy(
        address asset,
        address destination,
        uint256 amount
    ) internal {
        // Grant controller role to Spark Proxy
        MainnetController(Ethereum.ALM_PROXY).grantRole(
            IALMProxy(Ethereum.ALM_PROXY).CONTROLLER(),
            Ethereum.SPARK_PROXY
        );

        IALMProxy(Ethereum.ALM_PROXY).doCall(
            asset,
            abi.encodeCall(
                IERC20(asset).transfer,
                (destination, amount)
            )
        );

        // Revoke controller role from Spark Proxy
        MainnetController(Ethereum.ALM_PROXY).revokeRole(
            IALMProxy(Ethereum.ALM_PROXY).CONTROLLER(),
            Ethereum.SPARK_PROXY
        );
    }

    function _transferFromSparkLendTreasury(address[] memory aTokens) internal {
        address[] memory assets = new address[](aTokens.length);

        for (uint256 i; i < aTokens.length; i++) {
            assets[i] = IAToken(aTokens[i]).UNDERLYING_ASSET_ADDRESS();
        }

        IPool(SparkLend.POOL).mintToTreasury(assets);

        for (uint256 i; i < aTokens.length; i++) {
            address treasury = aTokens[i] == SparkLend.DAI_SPTOKEN
                ? SparkLend.DAI_TREASURY
                : SparkLend.TREASURY;

            ITreasuryControllerLike(SparkLend.TREASURY_CONTROLLER).transfer({
                collector: treasury,
                token:     aTokens[i],
                recipient: Ethereum.ALM_PROXY,
                amount:    IERC20(aTokens[i]).balanceOf(treasury)
            });
        }
    }

    function _setUpNewMorphoVault(
        address               asset,
        string         memory name,
        string         memory symbol,
        MarketParams[] memory markets,
        uint256[]      memory caps,
        uint256               vaultFee,
        uint256               initialDeposit,
        uint256               sllDepositMax,
        uint256               sllDepositSlope
    ) internal {
        IMetaMorpho vault = IMetaMorphoFactory(Ethereum.MORPHO_FACTORY).createMetaMorpho({
            initialOwner:    Ethereum.SPARK_PROXY,
            initialTimelock: 0,
            asset:           asset,
            name:            name,
            symbol:          symbol,
            salt:            ""
        });

        require(markets.length == caps.length, "Markets and caps length mismatch");

        for (uint256 i; i < markets.length; i++) {
            vault.submitCap(markets[i], caps[i]);
            vault.acceptCap(markets[i]);
        }

        // Submit and accept cap for idle market
        MarketParams memory idleMarket = SLLHelpers.morphoIdleMarket(asset);
        vault.submitCap(idleMarket, type(uint184).max);
        vault.acceptCap(idleMarket);

        // Add idle market to supply queue
        Id[] memory ids = new Id[](1);
        ids[0] = MarketParamsLib.id(idleMarket);

        vault.setSupplyQueue(ids);

        // Set ALM Relayer as allocator.
        vault.setIsAllocator(
            Ethereum.ALM_RELAYER_MULTISIG,
            true
        );

        // Set Vault Fee Recipient and Fee
        vault.setFeeRecipient(Ethereum.ALM_PROXY);
        vault.setFee(vaultFee);

        // Seed vault with initial deposit
        IERC20(asset).approve(address(vault), initialDeposit);
        IERC4626(address(vault)).deposit(initialDeposit, address(1));

        // Submit timelock for vault (Increases are immediate)
        vault.submitTimelock(1 days);

        if (sllDepositMax != 0 && sllDepositSlope != 0) {
            _configureERC4626Vault(
                address(vault),
                sllDepositMax,
                sllDepositSlope
            );
        }
    }

    function _sendOpTokens(address fromToken, address toToken, uint256 amount) internal {
        IERC20(fromToken).approve(Ethereum.OPTIMISM_TOKEN_BRIDGE, amount);

        IOptimismTokenBridge(Ethereum.OPTIMISM_TOKEN_BRIDGE).bridgeERC20To({
            _localToken  : fromToken,
            _remoteToken : toToken,
            _to          : Optimism.ALM_PROXY,
            _amount      : amount,
            _minGasLimit : 1_000_000,
            _extraData   : ""
        });
    }

    function _sendArbTokens(address token, uint256 amount) internal {
        // Gas submission adapted from ArbitrumForwarder.sendMessageL1toL2
        bytes memory finalizeDepositCalldata = IArbitrumTokenBridge(Ethereum.ARBITRUM_TOKEN_BRIDGE).getOutboundCalldata({
            l1Token : token,
            from    : address(this),
            to      : Arbitrum.ALM_PROXY,
            amount  : amount,
            data    : ""
        });

        uint256 gasLimit      = 1_000_000;
        uint256 baseFee       = block.basefee;
        uint256 maxFeePerGas  = 50e9;
        uint256 maxSubmission = ICrossDomainArbitrum(ArbitrumForwarder.L1_CROSS_DOMAIN_ARBITRUM_ONE).calculateRetryableSubmissionFee(finalizeDepositCalldata.length, baseFee);
        uint256 maxRedemption = gasLimit * maxFeePerGas;

        IERC20(token).approve(Ethereum.ARBITRUM_TOKEN_BRIDGE, amount);
        IArbitrumTokenBridge(Ethereum.ARBITRUM_TOKEN_BRIDGE).outboundTransfer{value: maxSubmission + maxRedemption}({
            l1Token     : token, 
            to          : Arbitrum.ALM_PROXY, 
            amount      : amount, 
            maxGas      : gasLimit, 
            gasPriceBid : maxFeePerGas,
            data        : abi.encode(maxSubmission, bytes(""))
        });
    }

}
"
    },
    "src/interfaces/Interfaces.sol": {
      "content": "// SPDX-License-Identifier: AGPL-3.0

pragma solidity >=0.7.5 <0.9.0;

import { IERC20 }   from "forge-std/interfaces/IERC20.sol";
import { IERC4626 } from "forge-std/interfaces/IERC4626.sol";
import { IERC7540 } from "forge-std/interfaces/IERC7540.sol";

import { Id } from "metamorpho/interfaces/IMetaMorpho.sol";

import { IALMProxy } from "spark-alm-controller/src/interfaces/IALMProxy.sol";

interface IALMProxyFreezableLike is IALMProxy {
    function FREEZER() external returns (bytes32);
    function DEFAULT_ADMIN_ROLE() external returns (bytes32);
}

interface IArbitrumTokenBridge {
    function outboundTransfer(
        address l1Token,
        address to,
        uint256 amount,
        uint256 maxGas,
        uint256 gasPriceBid,
        bytes calldata data
    ) external payable returns (bytes memory res);
    function getOutboundCalldata(
        address l1Token,
        address from,
        address to,
        uint256 amount,
        bytes memory data
    ) external pure returns (bytes memory outboundCalldata);
}

interface IProxyLike {

    function implementation() external view returns (address);

}

interface IOptimismTokenBridge {
    function bridgeERC20To(
        address _localToken,
        address _remoteToken,
        address _to,
        uint256 _amount,
        uint32 _minGasLimit,
        bytes calldata _extraData
    ) external;
}

interface IOracleLike {

    function DECIMALS() external view returns (uint8);

    function decimals() external view returns (uint8);

    function description() external view returns (string memory);

    function name() external view returns (string memory);

    function version() external view returns (uint256);

    function latestAnswer() external view returns (int256);

}

interface ITreasuryControllerLike {

    function transfer(
        address collector,
        address token,
        address recipient,
        uint256 amount
    ) external;

}

interface IStarGuardLike {
    function plot(address addr_, bytes32 tag_) external;
    function exec() external returns (address addr);
}

interface ISparkVaultV2Like {

    function asset() external view returns (address);

    function assetsOf(address user) external view returns (uint256);

    function balanceOf(address user) external view returns (uint256);

    function chi() external view returns (uint192);

    function decimals() external view returns (uint8);

    function DEFAULT_ADMIN_ROLE() external view returns (bytes32);

    function deposit(uint256 assets, address receiver) external returns (uint256 shares);

    function depositCap() external view returns (uint256);

    function getRoleMemberCount(bytes32 role) external view returns (uint256);

    function grantRole(bytes32 role, address account) external; 

    function hasRole(bytes32 role, address account) external view returns (bool);

    function minVsr() external view returns (uint256);

    function maxDeposit(address) external view returns (uint256);

    function maxVsr() external view returns (uint256);

    function name() external view returns (string memory);

    function nowChi() external view returns (uint256);

    function redeem(uint256 shares, address receiver, address owner) external returns (uint256 assets);

    function revokeRole(bytes32 role, address account) external;

    function rho() external view returns (uint64);

    function setDepositCap(uint256 newCap) external;

    function SETTER_ROLE() external view returns (bytes32);

    function setVsr(uint256 newVsr) external;

    function setVsrBounds(uint256 minVsr_, uint256 maxVsr_) external;

    function symbol() external view returns (string memory);

    function TAKER_ROLE() external view returns (bytes32);

    function totalAssets() external view returns (uint256);

    function totalSupply() external view returns (uint256);

    function vsr() external view returns (uint256);

}

interface IAuthorityLike {

    function canCall(address src, address dst, bytes4 sig) external view returns (bool);

    function hat() external view returns (address);

    function lock(uint256 amount) external;

    function vote(address[] calldata slate) external;

    function lift(address target) external;

}

interface ICustomIRMLike {

    function RATE_SOURCE() external view returns (address);

    function getBaseVariableBorrowRateSpread() external view returns (uint256);

}

interface IExecutableLike {

    function execute() external;

}

interface IMorphoLike {

    struct Position {
        uint256 supplyShares;
        uint128 borrowShares;
        uint128 collateral;
    }

    function position(Id id, address user) external view returns (Position memory p);

    function market(Id id)
        external
        view
        returns (
            uint128 totalSupplyAssets,
            uint128 totalSupplyShares,
            uint128 totalBorrowAssets,
            uint128 totalBorrowShares,
            uint128 lastUpdate,
            uint128 fee
        );

}

