    "src/libraries/SLLHelpers.sol": {
      "content": "// SPDX-License-Identifier: AGPL-3.0

pragma solidity ^0.8.0;

import { IAToken } from "aave-v3-origin/src/core/contracts/interfaces/IAToken.sol";

import { IERC4626 } from "forge-std/interfaces/IERC4626.sol";

import { IMetaMorpho } from "metamorpho/interfaces/IMetaMorpho.sol";

import { MarketParams, Id } from "morpho-blue/src/interfaces/IMorpho.sol";
import { MarketParamsLib }  from "morpho-blue/src/libraries/MarketParamsLib.sol";

import { SafeERC20, IERC20 } from "openzeppelin-contracts/contracts/token/ERC20/utils/SafeERC20.sol";
import { IERC20Metadata }    from "openzeppelin-contracts/contracts/token/ERC20/extensions/IERC20Metadata.sol";

import { Arbitrum }  from "spark-address-registry/Arbitrum.sol";
import { Avalanche } from "spark-address-registry/Avalanche.sol";
import { Base }      from "spark-address-registry/Base.sol";
import { Ethereum }  from "spark-address-registry/Ethereum.sol";
import { Optimism }  from "spark-address-registry/Optimism.sol";
import { Unichain }  from "spark-address-registry/Unichain.sol";

import { ControllerInstance }    from "spark-alm-controller/deploy/ControllerInstance.sol";
import { MainnetControllerInit } from "spark-alm-controller/deploy/MainnetControllerInit.sol";
import { ForeignControllerInit } from "spark-alm-controller/deploy/ForeignControllerInit.sol";
import { IRateLimits }           from "spark-alm-controller/src/interfaces/IRateLimits.sol";
import { MainnetController }     from "spark-alm-controller/src/MainnetController.sol";
import { RateLimitHelpers }      from "spark-alm-controller/src/RateLimitHelpers.sol";

import { CCTPForwarder } from "xchain-helpers/forwarders/CCTPForwarder.sol";

import { ISparkVaultV2Like } from "src/interfaces/Interfaces.sol";

/**
 * @notice Helper functions for Spark Liquidity Layer
 */
library SLLHelpers {

    struct RateLimitData {
        uint256 maxAmount;
        uint256 slope;
    }

    // This is the same on all chains
    address internal constant MORPHO = 0xBBBBBbbBBb9cC5e90e3b3Af64bdAF62C37EEFFCb;

    bytes32 internal constant LIMIT_4626_DEPOSIT   = keccak256("LIMIT_4626_DEPOSIT");
    bytes32 internal constant LIMIT_4626_WITHDRAW  = keccak256("LIMIT_4626_WITHDRAW");
    bytes32 internal constant LIMIT_AAVE_DEPOSIT   = keccak256("LIMIT_AAVE_DEPOSIT");
    bytes32 internal constant LIMIT_AAVE_WITHDRAW  = keccak256("LIMIT_AAVE_WITHDRAW");
    bytes32 internal constant LIMIT_USDS_MINT      = keccak256("LIMIT_USDS_MINT");
    bytes32 internal constant LIMIT_USDS_TO_USDC   = keccak256("LIMIT_USDS_TO_USDC");
    bytes32 internal constant LIMIT_USDC_TO_CCTP   = keccak256("LIMIT_USDC_TO_CCTP");
    bytes32 internal constant LIMIT_USDC_TO_DOMAIN = keccak256("LIMIT_USDC_TO_DOMAIN");
    bytes32 internal constant LIMIT_PSM_DEPOSIT    = keccak256("LIMIT_PSM_DEPOSIT");
    bytes32 internal constant LIMIT_PSM_WITHDRAW   = keccak256("LIMIT_PSM_WITHDRAW");
    bytes32 internal constant LIMIT_CURVE_DEPOSIT  = keccak256("LIMIT_CURVE_DEPOSIT");
    bytes32 internal constant LIMIT_CURVE_SWAP     = keccak256("LIMIT_CURVE_SWAP");
    bytes32 internal constant LIMIT_CURVE_WITHDRAW = keccak256("LIMIT_CURVE_WITHDRAW");

    /**
     * @notice Activate the bare minimum for Spark Liquidity Layer
     * @dev Sets PSM and CCTP rate limits.
     */
    function activateSparkLiquidityLayer(
        address rateLimits,
        address usdc,
        address usds,
        address susds,
        RateLimitData memory usdcDeposit,
        RateLimitData memory usdcWithdraw,
        RateLimitData memory cctpEthereumDeposit
    ) internal {
        // PSM USDC
        setRateLimitData(
            RateLimitHelpers.makeAddressKey(
                LIMIT_PSM_DEPOSIT,
                usdc
            ),
            rateLimits,
            usdcDeposit.maxAmount,
            usdcDeposit.slope,
            6
        );

        setRateLimitData(
            RateLimitHelpers.makeAddressKey(
                LIMIT_PSM_WITHDRAW,
                usdc
            ),
            rateLimits,
            usdcWithdraw.maxAmount,
            usdcWithdraw.slope,
            6
        );

        // PSM USDS
        IRateLimits(rateLimits).setUnlimitedRateLimitData(
            RateLimitHelpers.makeAddressKey(
                LIMIT_PSM_DEPOSIT,
                usds
            )
        );

        IRateLimits(rateLimits).setUnlimitedRateLimitData(
            RateLimitHelpers.makeAddressKey(
                LIMIT_PSM_WITHDRAW,
                usds
            )
        );

        // PSM sUSDS
        IRateLimits(rateLimits).setUnlimitedRateLimitData(
            RateLimitHelpers.makeAddressKey(
                LIMIT_PSM_DEPOSIT,
                susds
            )
        );

        IRateLimits(rateLimits).setUnlimitedRateLimitData(
            RateLimitHelpers.makeAddressKey(
                LIMIT_PSM_WITHDRAW,
                susds
            )
        );

        // CCTP
        IRateLimits(rateLimits).setUnlimitedRateLimitData(
            LIMIT_USDC_TO_CCTP
        );

        setRateLimitData(
            RateLimitHelpers.makeUint32Key(
                LIMIT_USDC_TO_DOMAIN,
                0  // Ethereum domain id (https://developers.circle.com/stablecoins/evm-smart-contracts)
            ),
            rateLimits,
            cctpEthereumDeposit.maxAmount,
            cctpEthereumDeposit.slope,
            6
        );
    }

    /**
     * @notice Configure an Aave token
     * @dev This will set the deposit to the given numbers with
     *      the withdraw limit set to unlimited.
     */
    function configureAaveToken(
        address rateLimits,
        address token,
        uint256 depositMax,
        uint256 depositSlope
    ) internal {
        IERC20 underlying = IERC20(IAToken(token).UNDERLYING_ASSET_ADDRESS());

        setRateLimitData(
            RateLimitHelpers.makeAddressKey(
                LIMIT_AAVE_DEPOSIT,
                token
            ),
            rateLimits,
            depositMax,
            depositSlope,
            IERC20Metadata(address(underlying)).decimals()
        );

        IRateLimits(rateLimits).setUnlimitedRateLimitData(
            RateLimitHelpers.makeAddressKey(
                LIMIT_AAVE_WITHDRAW,
                token
            )
        );
    }

    /**
     * @notice Configure an ERC4626 vault
     * @dev This will set the deposit to the given numbers with
     *      the withdraw limit set to unlimited.
     */
    function configureERC4626Vault(
        address rateLimits,
        address vault,
        uint256 depositMax,
        uint256 depositSlope
    ) internal {
        IERC20 asset = IERC20(IERC4626(vault).asset());

        setRateLimitData(
            RateLimitHelpers.makeAddressKey(
                LIMIT_4626_DEPOSIT,
                vault
            ),
            rateLimits,
            depositMax,
            depositSlope,
            IERC20Metadata(address(asset)).decimals()
        );

        IRateLimits(rateLimits).setUnlimitedRateLimitData(
            RateLimitHelpers.makeAddressKey(
                LIMIT_4626_WITHDRAW,
                vault
            )
        );

        MainnetController(Ethereum.ALM_CONTROLLER).setMaxExchangeRate(
            vault,
            1 * 10 ** IERC20Metadata(vault).decimals(),
            10 * 10 ** IERC20Metadata(address(asset)).decimals()
        );
    }

    function setMaxExchangeRate(
        address almController,
        address vault, 
        uint256 normalizedShares, 
        uint256 normalizedAssets
    ) 
        internal 
    {
        uint256 sharePrecision = 10 ** IERC20Metadata(vault).decimals();
        uint256 assetPrecision = 10 ** IERC20Metadata(IERC4626(vault).asset()).decimals();

        MainnetController(almController).setMaxExchangeRate({
            token             : vault,
            shares            : normalizedShares * sharePrecision,
            maxExpectedAssets : normalizedAssets * assetPrecision
        });
    }

    /**
     * @notice Onboard a Curve pool
     */
    function configureCurvePool(
        address controller,
        address rateLimits,
        address pool,
        uint256 maxSlippage,
        uint256 swapMax,
        uint256 swapSlope,
        uint256 depositMax,
        uint256 depositSlope,
        uint256 withdrawMax,
        uint256 withdrawSlope
    ) internal {
        MainnetController(controller).setMaxSlippage(pool, maxSlippage);

        if (swapMax != 0) {
            setRateLimitData(
                RateLimitHelpers.makeAddressKey(
                    LIMIT_CURVE_SWAP,
                    pool
                ),
                rateLimits,
                swapMax,
                swapSlope,
                18
            );
        }

        if (depositMax != 0) {
            setRateLimitData(
                RateLimitHelpers.makeAddressKey(
                    LIMIT_CURVE_DEPOSIT,
                    pool
                ),
                rateLimits,
                depositMax,
                depositSlope,
                18
            );
        }

        if (withdrawMax != 0) {
            setRateLimitData(
                RateLimitHelpers.makeAddressKey(
                    LIMIT_CURVE_WITHDRAW,
                    pool
                ),
                rateLimits,
                withdrawMax,
                withdrawSlope,
                18
            );
        }
    }

    function morphoIdleMarket(
        address asset
    ) internal pure returns (MarketParams memory) {
        return MarketParams({
            loanToken:       asset,
            collateralToken: address(0),
            oracle:          address(0),
            irm:             address(0),
            lltv:            0
        });
    }

    /**
     * @notice Activate a Morpho Vault
     * @dev This will do the following:
     *      - Add the relayer as an allocator
     *      - Add the idle market for the underlying asset with unlimited size
     *      - Set the supply queue to the idle market
     */
    function activateMorphoVault(
        address vault,
        address relayer
    ) internal {
        IERC20 asset = IERC20(IERC4626(vault).asset());
        MarketParams memory idleMarket = morphoIdleMarket(address(asset));

        IMetaMorpho(vault).setIsAllocator(
            relayer,
            true
        );

        IMetaMorpho(vault).submitCap(
            idleMarket,
            type(uint184).max
        );

        IMetaMorpho(vault).acceptCap(
            idleMarket
        );

        Id[] memory supplyQueue = new Id[](1);
        supplyQueue[0] = MarketParamsLib.id(idleMarket);
        IMetaMorpho(vault).setSupplyQueue(supplyQueue);
    }

    function setUSDSMintRateLimit(
        address rateLimits,
        uint256 maxAmount,
        uint256 slope
    ) internal {
        setRateLimitData(
            LIMIT_USDS_MINT,
            rateLimits,
            maxAmount,
            slope,
            18
        );
    }

    function setUSDSToUSDCRateLimit(
        address rateLimits,
        uint256 maxUsdcAmount,
        uint256 slope
    ) internal {
        setRateLimitData(
            LIMIT_USDS_TO_USDC,
            rateLimits,
            maxUsdcAmount,
            slope,
            6
        );
    }

    function setUSDCToCCTPRateLimit(
        address rateLimits,
        uint256 maxUsdcAmount,
        uint256 slope
    ) internal {
        setRateLimitData(
            LIMIT_USDC_TO_CCTP,
            rateLimits,
            maxUsdcAmount,
            slope,
            6
        );
    }

    function setUSDCToDomainRateLimit(
        address rateLimits,
        uint32  destinationDomain,
        uint256 maxUsdcAmount,
        uint256 slope
    ) internal {
        setRateLimitData(
            RateLimitHelpers.makeUint32Key(LIMIT_USDC_TO_DOMAIN, destinationDomain),
            rateLimits,
            maxUsdcAmount,
            slope,
            6
        );
    }

    function addrToBytes32(address addr) internal pure returns (bytes32) {
        return bytes32(uint256(uint160(addr)));
    }

    function upgradeMainnetController(address oldController, address newController) internal {
        MainnetControllerInit.MintRecipient[] memory mintRecipients = new MainnetControllerInit.MintRecipient[](5);

        mintRecipients[0] = MainnetControllerInit.MintRecipient({
            domain        : CCTPForwarder.DOMAIN_ID_CIRCLE_BASE,
            mintRecipient : addrToBytes32(Base.ALM_PROXY)
        });

        mintRecipients[1] = MainnetControllerInit.MintRecipient({
            domain        : CCTPForwarder.DOMAIN_ID_CIRCLE_ARBITRUM_ONE,
            mintRecipient : addrToBytes32(Arbitrum.ALM_PROXY)
        });

        mintRecipients[2] = MainnetControllerInit.MintRecipient({
            domain        : CCTPForwarder.DOMAIN_ID_CIRCLE_OPTIMISM,
            mintRecipient : addrToBytes32(Optimism.ALM_PROXY)
        });

        mintRecipients[3] = MainnetControllerInit.MintRecipient({
            domain        : CCTPForwarder.DOMAIN_ID_CIRCLE_UNICHAIN,
            mintRecipient : addrToBytes32(Unichain.ALM_PROXY)
        });

        mintRecipients[4] = MainnetControllerInit.MintRecipient({
            domain        : CCTPForwarder.DOMAIN_ID_CIRCLE_AVALANCHE,
            mintRecipient : addrToBytes32(Avalanche.ALM_PROXY)
        });

        MainnetControllerInit.LayerZeroRecipient[] memory layerZeroRecipients = new MainnetControllerInit.LayerZeroRecipient[](0);

        MainnetControllerInit.MaxSlippageParams[] memory maxSlippageParams = new MainnetControllerInit.MaxSlippageParams[](4);

        maxSlippageParams[0] = MainnetControllerInit.MaxSlippageParams({
            pool        : Ethereum.CURVE_SUSDSUSDT,
            maxSlippage : MainnetController(Ethereum.ALM_CONTROLLER).maxSlippages(Ethereum.CURVE_SUSDSUSDT)
        });

        maxSlippageParams[1] = MainnetControllerInit.MaxSlippageParams({
            pool        : Ethereum.CURVE_PYUSDUSDC,
            maxSlippage : MainnetController(Ethereum.ALM_CONTROLLER).maxSlippages(Ethereum.CURVE_PYUSDUSDC)
        });

        maxSlippageParams[2] = MainnetControllerInit.MaxSlippageParams({
            pool        : Ethereum.CURVE_USDCUSDT,
            maxSlippage : MainnetController(Ethereum.ALM_CONTROLLER).maxSlippages(Ethereum.CURVE_USDCUSDT)
        });

        maxSlippageParams[3] = MainnetControllerInit.MaxSlippageParams({
            pool        : Ethereum.CURVE_PYUSDUSDS,
            maxSlippage : MainnetController(Ethereum.ALM_CONTROLLER).maxSlippages(Ethereum.CURVE_PYUSDUSDS)
        });

        address[] memory relayers = new address[](2);
        relayers[0] = Ethereum.ALM_RELAYER_MULTISIG;
        relayers[1] = Ethereum.ALM_BACKSTOP_RELAYER_MULTISIG;

        MainnetControllerInit.upgradeController({
            controllerInst: ControllerInstance({
                almProxy   : Ethereum.ALM_PROXY,
                controller : newController,
                rateLimits : Ethereum.ALM_RATE_LIMITS
            }),
            configAddresses: MainnetControllerInit.ConfigAddressParams({
                freezer       : Ethereum.ALM_FREEZER_MULTISIG,
                relayers      : relayers,
                oldController : oldController
            }),
            checkAddresses: MainnetControllerInit.CheckAddressParams({
                admin      : Ethereum.SPARK_PROXY,
                proxy      : Ethereum.ALM_PROXY,
                rateLimits : Ethereum.ALM_RATE_LIMITS,
                vault      : Ethereum.ALLOCATOR_VAULT,
                psm        : Ethereum.PSM,
                daiUsds    : Ethereum.DAI_USDS,
                cctp       : Ethereum.CCTP_TOKEN_MESSENGER
            }),
            mintRecipients:      mintRecipients,
            layerZeroRecipients: layerZeroRecipients,
            maxSlippageParams:   maxSlippageParams
        });
    }

    function upgradeForeignController(
        ControllerInstance memory controllerInst,
        ForeignControllerInit.ConfigAddressParams memory configAddresses,
        ForeignControllerInit.CheckAddressParams memory checkAddresses,
        bool checkPsm
    ) internal {
        ForeignControllerInit.MintRecipient[] memory mintRecipients = new ForeignControllerInit.MintRecipient[](1);

        mintRecipients[0] = ForeignControllerInit.MintRecipient({
            domain        : CCTPForwarder.DOMAIN_ID_CIRCLE_ETHEREUM,
            mintRecipient : addrToBytes32(Ethereum.ALM_PROXY)
        });

        ForeignControllerInit.LayerZeroRecipient[] memory layerZeroRecipients = new ForeignControllerInit.LayerZeroRecipient[](0);

        ForeignControllerInit.MaxSlippageParams[] memory maxSlippageParams = new ForeignControllerInit.MaxSlippageParams[](0);

        ForeignControllerInit.upgradeController({
            controllerInst:      controllerInst,
            configAddresses:     configAddresses,
            checkAddresses:      checkAddresses,
            mintRecipients:      mintRecipients,
            layerZeroRecipients: layerZeroRecipients,
            maxSlippageParams:   maxSlippageParams,
            checkPsm:            checkPsm
        });
    }

    function setRateLimitData(
        bytes32 key,
        address rateLimits,
        uint256 maxAmount,
        uint256 slope,
        uint256 decimals
    )
        internal
    {
        // Handle setting an unlimited rate limit
        if (maxAmount == type(uint256).max) {
            require(slope == 0, "InvalidUnlimitedRateLimitSlope");
        } else {
            uint256 upperBound = 1e12 * (10 ** decimals);
            uint256 lowerBound = 10 ** decimals;

            require(maxAmount <= upperBound && maxAmount >= lowerBound,             "InvalidMaxAmountPrecision");
            require(slope <= upperBound / 1 hours && slope >= lowerBound / 1 hours, "InvalidSlopePrecision");
            require(slope != 0,                                                     "InvalidSlopePrecision");
        }

        IRateLimits(rateLimits).setRateLimitData(key, maxAmount, slope);
    }

    function configureVaultsV2(
        address vault_,
        uint256 supplyCap,
        uint256 minVsr,
        uint256 maxVsr,
        uint256 depositAmount,
        address ratelimits_,
        address controller_,
        address setter,
        address taker
    ) internal {
        ISparkVaultV2Like vault      = ISparkVaultV2Like(vault_);
        IRateLimits       rateLimits = IRateLimits(ratelimits_);
        MainnetController controller = MainnetController(controller_);

        // Grant SETTER_ROLE to ALM Proxy Freezable
        vault.grantRole(vault.SETTER_ROLE(), setter);

        // Grant TAKER_ROLE to Alm Proxy
        vault.grantRole(vault.TAKER_ROLE(), taker);

        // Set VSR bounds
        vault.setVsrBounds(minVsr, maxVsr);

        // Set the supply cap
        vault.setDepositCap(supplyCap);

        // Deposit into the vault
        SafeERC20.safeIncreaseAllowance(IERC20(vault.asset()), vault_, depositAmount);
        vault.deposit(depositAmount, address(1));

        rateLimits.setUnlimitedRateLimitData(
            RateLimitHelpers.makeAddressKey(
                controller.LIMIT_SPARK_VAULT_TAKE(),
                address(vault)
            )
        );

        rateLimits.setUnlimitedRateLimitData(
            RateLimitHelpers.makeAddressAddressKey(
                controller.LIMIT_ASSET_TRANSFER(),
                vault.asset(),
                address(vault)
            )
        );
    }

}
"
    },
    "src/AaveV3PayloadBase.sol": {
      "content": "// SPDX-License-Identifier: MIT

pragma solidity ^0.8.0;

import { Address } from "./libraries/Address.sol";

import { IAaveV3ConfigEngine as IEngine } from "./interfaces/IAaveV3ConfigEngine.sol";

library EngineFlags {

    /// @dev Magic value to be used as flag to keep unchanged any current configuration.
    /// Strongly assumes that the value `type(uint256).max - 42` will never be used, which seems reasonable.
    uint256 internal constant KEEP_CURRENT = type(uint256).max - 42;

    /// @dev Value to be used as flag for bool value true.
    uint256 internal constant ENABLED = 1;

    /// @dev Value to be used as flag for bool value false.
    uint256 internal constant DISABLED = 0;

    /// @dev Converts flag ENABLED DISABLED to bool.
    function toBool(uint256 flag) internal pure returns (bool) {
        require(flag == 0 || flag == 1, "INVALID_CONVERSION_TO_BOOL");
        return flag == 1;
    }

    /// @dev Converts bool to ENABLED DISABLED flags.
    function fromBool(bool isTrue) internal pure returns (uint256) {
        return isTrue ? ENABLED : DISABLED;
    }

}

/**
 * @dev Base smart contract for an Aave v3.0.1 configs update.
 * - Assumes this contract has the right permissions
 * - Connected to a IAaveV3ConfigEngine engine contact, which abstract the complexities of
 *   interaction with the Aave protocol.
 * - At the moment covering:
 *   - Listings of new assets on the pool.
 *   - Updates of caps (supply cap, borrow cap).
 *   - Updates of price feeds
 *   - Updates of interest rate strategies.
 *   - Updates of borrow parameters (flashloanable, stableRateModeEnabled, borrowableInIsolation, withSiloedBorrowing, reserveFactor)
 *   - Updates of collateral parameters (ltv, liq threshold, liq bonus, liq protocol fee, debt ceiling)
 * @author BGD Labs
 */
abstract contract AaveV3PayloadBase {

    using Address for address;

    IEngine public immutable LISTING_ENGINE;

    constructor(address engine) {
        LISTING_ENGINE = IEngine(engine);
    }

    /// @dev To be overridden on the child if any extra logic is needed pre-listing.
    function _preExecute() internal virtual {}

    /// @dev To be overridden on the child if any extra logic is needed post-listing.
    function _postExecute() internal virtual {}

    function execute() public virtual {
        _preExecute();

        IEngine.Listing[] memory listings = newListings();
        IEngine.ListingWithCustomImpl[] memory listingsCustom = newListingsCustom();
        IEngine.CapsUpdate[] memory caps = capsUpdates();
        IEngine.CollateralUpdate[] memory collaterals = collateralsUpdates();
        IEngine.BorrowUpdate[] memory borrows = borrowsUpdates();
        IEngine.PriceFeedUpdate[] memory priceFeeds = priceFeedsUpdates();
        IEngine.RateStrategyUpdate[] memory rates = rateStrategiesUpdates();

        if (listings.length != 0) {
            address(LISTING_ENGINE).functionDelegateCall(
                abi.encodeWithSelector(LISTING_ENGINE.listAssets.selector, getPoolContext(), listings)
            );
        }

        if (listingsCustom.length != 0) {
            address(LISTING_ENGINE).functionDelegateCall(
                abi.encodeWithSelector(
                    LISTING_ENGINE.listAssetsCustom.selector,
                    getPoolContext(),
                    listingsCustom
                )
            );
        }

        if (borrows.length != 0) {
            address(LISTING_ENGINE).functionDelegateCall(
                abi.encodeWithSelector(LISTING_ENGINE.updateBorrowSide.selector, borrows)
            );
        }

        if (collaterals.length != 0) {
            address(LISTING_ENGINE).functionDelegateCall(
                abi.encodeWithSelector(LISTING_ENGINE.updateCollateralSide.selector, collaterals)
            );
        }

        if (rates.length != 0) {
            address(LISTING_ENGINE).functionDelegateCall(
                abi.encodeWithSelector(LISTING_ENGINE.updateRateStrategies.selector, rates)
            );
        }

        if (priceFeeds.length != 0) {
            address(LISTING_ENGINE).functionDelegateCall(
                abi.encodeWithSelector(LISTING_ENGINE.updatePriceFeeds.selector, priceFeeds)
            );
        }

        if (caps.length != 0) {
            address(LISTING_ENGINE).functionDelegateCall(
                abi.encodeWithSelector(LISTING_ENGINE.updateCaps.selector, caps)
            );
        }

        _postExecute();
    }

    /** @dev Converts basis points to RAY units.
     * e.g. 10_00 (10.00%) will return 100000000000000000000000000
     */
    function _bpsToRay(uint256 amount) internal pure returns (uint256) {
        return (amount * 1e27) / 10_000;
    }

    /// @dev To be defined in the child with a list of new assets to list.
    function newListings() public view virtual returns (IEngine.Listing[] memory) {}

    /// @dev To be defined in the child with a list of new assets to list (with custom a/v/s tokens implementations).
    function newListingsCustom()
        public
        view
        virtual
        returns (IEngine.ListingWithCustomImpl[] memory)
    {}

    /// @dev To be defined in the child with a list of caps to update.
    function capsUpdates() public view virtual returns (IEngine.CapsUpdate[] memory) {}

    /// @dev To be defined in the child with a list of collaterals' params to update.
    function collateralsUpdates() public view virtual returns (IEngine.CollateralUpdate[] memory) {}

    /// @dev To be defined in the child with a list of borrows' params to update.
    function borrowsUpdates() public view virtual returns (IEngine.BorrowUpdate[] memory) {}

    /// @dev To be defined in the child with a list of priceFeeds to update.
    function priceFeedsUpdates() public view virtual returns (IEngine.PriceFeedUpdate[] memory) {}

    /// @dev To be defined in the child with a list of set of parameters of rate strategies.
    function rateStrategiesUpdates()
        public
        view
        virtual
        returns (IEngine.RateStrategyUpdate[] memory)
    {}

    /// @dev The lack of support for immutable strings kinds of forces for this.
    /// Besides that, it can actually be useful being able to change the naming, but remote.
    function getPoolContext() public view virtual returns (IEngine.PoolContext memory);

}
"
    },
    "lib/forge-std/src/interfaces/IERC7540.sol": {
      "content": "// SPDX-License-Identifier: MIT
pragma solidity >=0.6.2;

import {IERC7575} from "./IERC7575.sol";

/// @dev Interface of the base operator logic of ERC7540, as defined in
/// https://eips.ethereum.org/EIPS/eip-7540
interface IERC7540Operator {
    /**
     * @dev The event emitted when an operator is set.
     *
     * @param controller The address of the controller.
     * @param operator The address of the operator.
     * @param approved The approval status.
     */
    event OperatorSet(address indexed controller, address indexed operator, bool approved);

    /**
     * @dev Sets or removes an operator for the caller.
     *
     * @param operator The address of the operator.
     * @param approved The approval status.
     * @return Whether the call was executed successfully or not
     */
    function setOperator(address operator, bool approved) external returns (bool);

    /**
     * @dev Returns `true` if the `operator` is approved as an operator for an `controller`.
     *
     * @param controller The address of the controller.
     * @param operator The address of the operator.
     * @return status The approval status
     */
    function isOperator(address controller, address operator) external view returns (bool status);
}

/// @dev Interface of the asynchronous deposit Vault interface of ERC7540, as defined in
/// https://eips.ethereum.org/EIPS/eip-7540
interface IERC7540Deposit is IERC7540Operator {
    event DepositRequest(
        address indexed controller, address indexed owner, uint256 indexed requestId, address sender, uint256 assets
    );
    /**
     * @dev Transfers assets from sender into the Vault and submits a Request for asynchronous deposit.
     *
     * - MUST support ERC-20 approve / transferFrom on asset as a deposit Request flow.
     * - MUST revert if all of assets cannot be requested for deposit.
     * - owner MUST be msg.sender unless some unspecified explicit approval is given by the caller,
     *    approval of ERC-20 tokens from owner to sender is NOT enough.
     *
     * @param assets the amount of deposit assets to transfer from owner
     * @param controller the controller of the request who will be able to operate the request
     * @param owner the source of the deposit assets
     *
     * NOTE: most implementations will require pre-approval of the Vault with the Vault's underlying asset token.
     */

    function requestDeposit(uint256 assets, address controller, address owner) external returns (uint256 requestId);

    /**
     * @dev Returns the amount of requested assets in Pending state.
     *
     * - MUST NOT include any assets in Claimable state for deposit or mint.
     * - MUST NOT show any variations depending on the caller.
     * - MUST NOT revert unless due to integer overflow caused by an unreasonably large input.
     */
    function pendingDepositRequest(uint256 requestId, address controller)
        external
        view
        returns (uint256 pendingAssets);

    /**
     * @dev Returns the amount of requested assets in Claimable state for the controller to deposit or mint.
     *
     * - MUST NOT include any assets in Pending state.
     * - MUST NOT show any variations depending on the caller.
     * - MUST NOT revert unless due to integer overflow caused by an unreasonably large input.
     */
    function claimableDepositRequest(uint256 requestId, address controller)
        external
        view
        returns (uint256 claimableAssets);

    /**
     * @dev Mints shares Vault shares to receiver by claiming the Request of the controller.
     *
     * - MUST emit the Deposit event.
     * - controller MUST equal msg.sender unless the controller has approved the msg.sender as an operator.
     */
    function deposit(uint256 assets, address receiver, address controller) external returns (uint256 shares);

    /**
     * @dev Mints exactly shares Vault shares to receiver by claiming the Request of the controller.
     *
     * - MUST emit the Deposit event.
     * - controller MUST equal msg.sender unless the controller has approved the msg.sender as an operator.
     */
    function mint(uint256 shares, address receiver, address controller) external returns (uint256 assets);
}

/// @dev Interface of the asynchronous deposit Vault interface of ERC7540, as defined in
/// https://eips.ethereum.org/EIPS/eip-7540
interface IERC7540Redeem is IERC7540Operator {
    event RedeemRequest(
        address indexed controller, address indexed owner, uint256 indexed requestId, address sender, uint256 assets
    );

    /**
     * @dev Assumes control of shares from sender into the Vault and submits a Request for asynchronous redeem.
     *
     * - MUST support a redeem Request flow where the control of shares is taken from sender directly
     *   where msg.sender has ERC-20 approval over the shares of owner.
     * - MUST revert if all of shares cannot be requested for redeem.
     *
     * @param shares the amount of shares to be redeemed to transfer from owner
     * @param controller the controller of the request who will be able to operate the request
     * @param owner the source of the shares to be redeemed
     *
     * NOTE: most implementations will require pre-approval of the Vault with the Vault's share token.
     */
    function requestRedeem(uint256 shares, address controller, address owner) external returns (uint256 requestId);

    /**
     * @dev Returns the amount of requested shares in Pending state.
     *
     * - MUST NOT include any shares in Claimable state for redeem or withdraw.
     * - MUST NOT show any variations depending on the caller.
     * - MUST NOT revert unless due to integer overflow caused by an unreasonably large input.
     */
    function pendingRedeemRequest(uint256 requestId, address controller)
        external
        view
        returns (uint256 pendingShares);

    /**
     * @dev Returns the amount of requested shares in Claimable state for the controller to redeem or withdraw.
     *
     * - MUST NOT include any shares in Pending state for redeem or withdraw.
     * - MUST NOT show any variations depending on the caller.
     * - MUST NOT revert unless due to integer overflow caused by an unreasonably large input.
     */
    function claimableRedeemRequest(uint256 requestId, address controller)
        external
        view
        returns (uint256 claimableShares);
}

/// @dev Interface of the fully asynchronous Vault interface of ERC7540, as defined in
/// https://eips.ethereum.org/EIPS/eip-7540
interface IERC7540 is IERC7540Deposit, IERC7540Redeem, IERC7575 {}
